draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw person
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 40);
  ctx.lineTo(W/2 - 70, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 40);
  ctx.lineTo(W/2 - 30, H/2 + 70);
  ctx.stroke();

  // draw tears
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 10 + 10 * Math.sin(t), 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2 - 20 + 10 * Math.sin(t + Math.PI/2), 5, 0, 2 * Math.PI);
  ctx.stroke();

  // draw dog
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 40);
  ctx.lineTo(W/2 + 30, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 40);
  ctx.lineTo(W/2 + 70, H/2 + 70);
  ctx.stroke();

  // draw dog's movement
  ctx.beginPath();
  ctx.moveTo(W/2 + 50 + 20 * Math.sin(t), H/2 + 100);
  ctx.lineTo(W/2 - 50, H/2 + 100);
  ctx.stroke();

  ctx.restore();
}
